package com.synexia.rewrite;

import com.sun.source.tree.*;
import com.sun.source.util.*;
import java.lang.reflect.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import javax.tools.*;

/** JDK-only qualification: real sealed preimages, replay, and compiler-extracted behavioral atoms. */
public final class Qualification {
  private static int checks;
  private Qualification() { }
  public static void main(String[] args) throws Exception {
    Path root = Path.of(args[0]).toRealPath();
    Path module = root.resolve(".m3/text-integration");
    Path data = module.resolve("dataset");
    Path scratch = Files.createTempDirectory("m3-text-qualification-");
    try {
      Path replay = Files.createDirectory(scratch.resolve("replay"));
      copyTree(module.resolve("preimages"), replay);
      M3TextRecipe.run(replay, data, true, null);
      check(M3TextRecipe.run(replay, data, true, null) == 0, "fixed point");
      check(M3TextRecipe.run(replay, data, false, null) == 0, "replay verification");
      M3TextRecipe.run(root, data, false, null);
      var manifest = M3GpuToolJoinManifest.load("/data/", n -> Files.newInputStream(data.resolve(n.substring(6))), () -> { });
      for (var t : manifest.targets()) check(Files.mismatch(root.resolve(t.path()), replay.resolve(t.path())) == -1, "exact generated bytes");
      var first = manifest.targets().iterator().next();
      Path victim = replay.resolve(first.path());
      Files.writeString(victim, Files.readString(victim) + "\n// drift\n");
      String drifted = Files.readString(victim);
      fails(IllegalStateException.class, () -> M3TextRecipe.run(replay, data, true, null));
      check(drifted.equals(Files.readString(victim)), "drift left intact");
      fails(CancellationException.class, () -> M3TextRecipe.run(root, data, true, () -> { throw new CancellationException(); }));
      Path badData = Files.createDirectory(scratch.resolve("bad-data"));
      copyTree(data, badData);
      Path template = badData.resolve(first.path().equals("") ? "never" : Files.readString(data.resolve("manifest.tsv")).split("\t")[3].strip().split("\\R")[0]);
      Files.writeString(template, Files.readString(template) + "\n// corruption\n");
      fails(IllegalStateException.class, () -> M3TextRecipe.run(root, badData, true, null));
      Files.writeString(badData.resolve("manifest.tsv"), "../outside\tABSENT\t" + first.after() + "\t000.template\n");
      fails(IllegalStateException.class, () -> M3TextRecipe.run(root, badData, true, null));
      Path linkRoot = Files.createDirectory(scratch.resolve("symlinks"));
      Path firstPart = Path.of(first.path()).getName(0);
      try {
        Files.createSymbolicLink(linkRoot.resolve(firstPart), root.resolve(firstPart));
        fails(IllegalStateException.class, () -> M3TextRecipe.run(linkRoot, data, true, null));
      } catch (UnsupportedOperationException | java.nio.file.FileSystemException unsupported) {
        System.out.println("SKIP symlink creation unavailable: " + unsupported.getClass().getSimpleName());
      }
      for (var t : manifest.targets()) {
        if (t.path().endsWith("/CharArrayMap.java")) lucene(root, module, scratch, t.path());
        if (t.path().endsWith("/DefaultTokenContextGenerator.java")) opennlp(root, module, scratch, t.path());
      }
      System.out.println("PASS checks=" + checks + "; recipe replay/drift/cancellation; " + System.getProperty("java.runtime.version"));
      System.out.println("Scope: source-seal and isolated behavioral atoms, NOT full upstream test suites or M3JDK runtime.");
    } finally { deleteTree(scratch); }
  }

  private static void lucene(Path root, Path module, Path scratch, String path) throws Exception {
    String before = Files.readString(module.resolve("preimages").resolve(path));
    String after = Files.readString(root.resolve(path));
    String mb = method(before, "getHashCode", "CharSequence", scratch);
    String ma = method(after, "getHashCode", "CharSequence", scratch);
    // Char-array and every other class byte stay identical after removing the admitted atom.
    check(before.replace(mb, "ATOM").equals(after.replace(ma, "ATOM")), "only admitted hash atom changed");
    Class<?> b = compile(scratch, "BeforeHash", hashClass("BeforeHash", mb));
    Class<?> a = compile(scratch, "AfterHash", hashClass("AfterHash", ma));
    Method be = b.getMethod("eval", CharSequence.class), ae = a.getMethod("eval", CharSequence.class);
    Random random = new Random(0x4d33);
    for (boolean ignore : new boolean[] {false, true}) {
      Object bo = b.getConstructor(boolean.class).newInstance(ignore), ao = a.getConstructor(boolean.class).newInstance(ignore);
      for (int c = 0; c <= 65535; c++) sameCall(be, bo, ae, ao, String.valueOf((char) c));
      for (int i = 0; i < 10000; i++) {
        char[] chars = new char[random.nextInt(100)];
        for (int j = 0; j < chars.length; j++) chars[j] = (char) random.nextInt(65536);
        String s = new String(chars);
        sameCall(be, bo, ae, ao, s);
        sameCall(be, bo, ae, ao, new StringBuilder(s));
        sameCall(be, bo, ae, ao, new Hostile(s));
      }
      sameCall(be, bo, ae, ao, (Object) null);
      sameCall(be, bo, ae, ao, "\uD800\uDC00\uE000\uD800");
    }
    System.out.println("PASS Lucene actual hash method; both case modes; all single UTF-16 units; 10000 random strings/builders/hostile sequences each mode.");
  }
  private static String hashClass(String name, String method) {
    return "public class " + name + " { private final boolean ignoreCase; public " + name + "(boolean b){ignoreCase=b;} " + method + " public int eval(CharSequence s){return getHashCode(s);} }";
  }
  private record Hostile(String value) implements CharSequence {
    public int length() { return value.length(); }
    public char charAt(int i) { return value.charAt(i); }
    public CharSequence subSequence(int a, int b) { return value.subSequence(a,b); }
    public int hashCode() { throw new AssertionError("must not invoke generic CharSequence.hashCode"); }
    public String toString() { throw new AssertionError("must not flatten generic CharSequence"); }
  }
  private static void opennlp(Path root, Path module, Path scratch, String path) throws Exception {
    String before = Files.readString(module.resolve("preimages").resolve(path));
    String after = Files.readString(root.resolve(path));
    String mb = method(before, "createContext", "String", scratch), ma = method(after, "createContext", "String", scratch);
    check(method(before,"getContext","String",scratch).equals(method(after,"getContext","String",scratch)), "public subclass hook entry unchanged");
    classifiers(before, after, scratch);
    Class<?> b = compile(scratch, "BeforeContext", contextClass("BeforeContext", mb));
    Class<?> a = compile(scratch, "AfterContext", contextClass("AfterContext", ma));
    Method be = b.getMethod("eval", String.class, int.class), ae = a.getMethod("eval", String.class, int.class);
    Random random = new Random(0x4d33);
    for (int i = 0; i < 5000; i++) {
      char[] chars = new char[random.nextInt(24)];
      for (int j = 0; j < chars.length; j++) chars[j] = (char) random.nextInt(65536);
      String s = i == 0 ? "&AbC;" : i == 1 ? "Dr." : new String(chars);
      for (boolean abbreviation : new boolean[] {false, true}) {
        Object bo = b.getConstructor(Set.class).newInstance(abbreviation ? Set.of(s) : Set.of());
        Object ao = a.getConstructor(Set.class).newInstance(abbreviation ? Set.of(s) : Set.of());
        for (int index = -1; index <= s.length(); index++) sameCall(be, bo, ae, ao, s, index);
      }
    }
    Object bo = b.getConstructor(Set.class).newInstance(Set.of()), ao = a.getConstructor(Set.class).newInstance(Set.of());
    sameCall(be, bo, ae, ao, null, 0);
    check(((List<?>) ae.invoke(ao, "&AbC;", 2)).size() == 18, "18 feature maximum reached with three-feature hooks");
    System.out.println("PASS OpenNLP actual createContext; order/duplicates/ranges/exceptions; context hook uses a three-feature test double; actual classification decisions qualified separately.");
  }
  private static void classifiers(String before, String after, Path scratch) throws Exception {
    String mb = method(before,"addCharPreds","String",scratch), ma = method(after,"addCharPreds","String",scratch);
    String helper = method(after,"categoryFeature","String",scratch);
    String expected = mb;
    String[] suffixes = {"_alpha","_caps","_num","_ws","_eos","_quote","_lp","_rp"};
    for(int i=0;i<suffixes.length;i++) expected = expected.replace("preds.add(key + \""+suffixes[i]+"\");", "preds.add(categoryFeature(key, "+i+"));");
    check(expected.equals(ma),"only category allocation atom changed; predicates unchanged");
    Class<?> b=compile(scratch,"BeforeCategories",categoryClass("BeforeCategories",mb,""));
    Class<?> a=compile(scratch,"AfterCategories",categoryClass("AfterCategories",ma,helper));
    Method be=b.getMethod("eval",String.class,char.class,boolean.class),ae=a.getMethod("eval",String.class,char.class,boolean.class);
    Object bo=b.getConstructor().newInstance(),ao=a.getConstructor().newInstance();
    for(String key:new String[]{"p1","p2","f1","f2","custom","",null}) {
      for(boolean whitespace:new boolean[]{false,true}) {
        for(int c=0;c<=65535;c++) sameCall(be,bo,ae,ao,key,(char)c,whitespace);
      }
    }
    List<?> first=(List<?>)ae.invoke(ao,"p1",'A',false);
    List<?> second=(List<?>)ae.invoke(ao,"p1",'A',false);
    check(first.get(1).equals("p1_alpha"),"category spelling");
    check(first.get(1)!=second.get(1) && first.get(1)!="p1_alpha", "fresh String wrappers preserved");
    System.out.println("PASS actual OpenNLP classifier: 7 keys x 2 injected whitespace outcomes x all UTF-16 units; fresh wrapper identity.");
  }
  private static String categoryClass(String name,String method,String helper) {
    return "import java.util.*; public class "+name+" { "+method+helper+
      " static class StringUtil {static boolean whitespace; static boolean isWhitespace(char c){return whitespace;}} "+
      "public List<String> eval(String key,char c,boolean ws){StringUtil.whitespace=ws;List<String> p=new ArrayList<>();addCharPreds(key,c,p);return p;} }";
  }
  private static String contextClass(String name, String method) {
    return "import java.util.*; public class " + name + " { protected final Set<String> inducedAbbreviations; public " + name + "(Set<String> s){inducedAbbreviations=s;} " + method +
        " protected void addCharPreds(String k,char c,List<String> p){p.add(k+\"=\"+c);p.add(k+\"_alpha\");p.add(k+\"_caps\");} public List<String> eval(String s,int i){return createContext(s,i);} }";
  }
  private static String method(String text, String name, String firstParam, Path dir) throws Exception {
    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    Path source = dir.resolve("Extraction.java"); Files.writeString(source, text);
    try (StandardJavaFileManager files = compiler.getStandardFileManager(null, null, null)) {
      JavacTask task = (JavacTask) compiler.getTask(null, files, null, List.of("-proc:none"), null, files.getJavaFileObjects(source));
      CompilationUnitTree unit = task.parse().iterator().next();
      SourcePositions positions = Trees.instance(task).getSourcePositions();
      List<String> found = new ArrayList<>();
      new TreeScanner<Void, Void>() {
        public Void visitMethod(MethodTree node, Void unused) {
          if (node.getName().contentEquals(name) && !node.getParameters().isEmpty()
              && node.getParameters().getFirst().getType().toString().equals(firstParam))
            found.add(text.substring((int) positions.getStartPosition(unit,node), (int) positions.getEndPosition(unit,node)));
          return super.visitMethod(node, unused);
        }
      }.scan(unit, null);
      check(found.size() == 1, "unique method selection"); return found.getFirst();
    }
  }
  private static Class<?> compile(Path scratch, String name, String source) throws Exception {
    Path dir = Files.createDirectory(scratch.resolve(name)); Path file = dir.resolve(name + ".java"); Files.writeString(file, source);
    check(ToolProvider.getSystemJavaCompiler().run(null, null, null, "--release", "21", "-d", dir.toString(), file.toString()) == 0, "compile actual method");
    try (URLClassLoader loader = new URLClassLoader(new URL[] {dir.toUri().toURL()})) {
      try (var files = Files.list(dir)) { for (Path c : files.filter(p -> p.toString().endsWith(".class")).toList()) {
        String binary = c.getFileName().toString(); loader.loadClass(binary.substring(0,binary.length()-6));
      }}
      return loader.loadClass(name);
    }
  }
  private static Object outcome(Method m, Object owner, Object... args) throws Exception {
    try { return m.invoke(owner, args); } catch (InvocationTargetException e) { return e.getCause().getClass(); }
  }
  private static void sameCall(Method b, Object bo, Method a, Object ao, Object... args) throws Exception {
    check(Objects.equals(outcome(b,bo,args), outcome(a,ao,args)), "differential behavior");
  }
  static void copyTree(Path source, Path target) throws Exception {
    if (!Files.exists(source)) return;
    try (var paths = Files.walk(source)) { for (Path p : paths.toList()) {
      Path to = target.resolve(source.relativize(p));
      if (Files.isDirectory(p)) Files.createDirectories(to); else { Files.createDirectories(to.getParent()); Files.copy(p,to,StandardCopyOption.REPLACE_EXISTING); }
    }}
  }
  static void deleteTree(Path p) throws Exception {
    try (var paths = Files.walk(p)) { for (Path file : paths.sorted(Comparator.reverseOrder()).toList()) Files.delete(file); }
  }
  static void check(boolean condition, String what) { checks++; if (!condition) throw new AssertionError(what); }
  interface Attempt { void run() throws Exception; }
  static void fails(Class<? extends Throwable> expected, Attempt action) throws Exception {
    try { action.run(); } catch (Throwable failure) { check(expected.isInstance(failure), "expected " + expected + " not " + failure); return; }
    throw new AssertionError("expected " + expected);
  }
}
